+    fn visual_spans_for_text(&self, pane: PaneFocus, text: &str) -> Vec<Spans<'static>> {
+        let spans = text
+            .lines()
+            .enumerate()
+            .map(|(row, line)| self.visual_spans_for_line(pane, row, line))
+            .collect::<Vec<_>>();
+        if spans.is_empty() {
+            vec![Spans::from(Span::raw(String::new()))]
+        } else {
+            spans
+        }
+    }
+
+    fn visual_spans_for_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Spans<'static> {
+        let Some((start, end)) = self.visual_selection_columns(pane, row, line) else {
+            return Spans::from(Span::raw(line.to_string()));
+        };
+        reversed_range_spans(line, start, end)
+    }
+
+    fn visual_selection_columns(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.pane != pane {
+            return None;
+        }
+        let line_len = line.chars().count();
+        match selection.mode {
+            VisualSelectionMode::Line => {
+                row_in_visual_range(selection, row).then_some((0, line_len))
+            }
+            VisualSelectionMode::Character => character_visual_columns(selection, row, line_len),
+            VisualSelectionMode::Block => block_visual_columns(selection, row, line_len),
+        }
+    }
+
+    fn visual_lines(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        let lines = match pane {
+            PaneFocus::Left => self
+                .left_pane_rows()
+                .into_iter()
+                .map(|row| row.text)
+                .collect::<Vec<_>>(),
+            PaneFocus::Right => self
+                .visible_right_content(right_content)
+                .lines()
+                .map(str::to_string)
+                .collect::<Vec<_>>(),
+        };
+        if lines.is_empty() {
+            vec![String::new()]
+        } else {
+            lines
+        }
+    }
+
+    fn begin_visual_selection(&mut self, mode: VisualSelectionMode, right_content: &str) {
+        let pane = if self.focus == PaneFocus::Left && self.left_visible {
+            PaneFocus::Left
+        } else {
+            PaneFocus::Right
+        };
+        let cursor = self.visual_start_position(pane, right_content);
+        self.mode = UiMode::Command;
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            mode,
+            anchor: cursor,
+            cursor,
+        });
+    }
+
+    fn handle_visual_key(&mut self, key: UiKey, right_content: &str) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.visual_selection = None;
+            }
+            UiKey::Char('v') => {
+                self.set_visual_mode(VisualSelectionMode::Character, right_content);
+            }
+            UiKey::Char('V') => {
+                self.set_visual_mode(VisualSelectionMode::Line, right_content);
+            }
+            UiKey::Char('\u{16}') => {
+                self.set_visual_mode(VisualSelectionMode::Block, right_content);
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1, right_content);
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0, right_content);
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0, right_content);
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1, right_content);
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn set_visual_mode(&mut self, mode: VisualSelectionMode, right_content: &str) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.mode = mode;
+            self.clamp_visual_selection(right_content);
+        } else {
+            self.begin_visual_selection(mode, right_content);
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+        let lines = self.visual_lines(selection.pane, right_content);
+        let max_row = lines.len().saturating_sub(1);
+        let next_row = offset_index(selection.cursor.row, row_delta, max_row);
+        let current_line_len = lines
+            .get(next_row)
+            .map(|line| line.chars().count())
+            .unwrap_or_default();
+        let next_column = if selection.mode == VisualSelectionMode::Line {
+            0
+        } else {
+            offset_index(selection.cursor.column, column_delta, current_line_len)
+        };
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = VisualPosition {
+                row: next_row,
+                column: next_column,
+            };
+        }
+    }
+
+    fn clamp_visual_selection(&mut self, right_content: &str) {
+        let Some(selection) = self.visual_selection.as_ref() else {
+            return;
+        };
+        let lines = self.visual_lines(selection.pane, right_content);
+        let max_row = lines.len().saturating_sub(1);
+        let mut anchor = selection.anchor;
+        let mut cursor = selection.cursor;
+        anchor.row = anchor.row.min(max_row);
+        cursor.row = cursor.row.min(max_row);
+        if selection.mode == VisualSelectionMode::Line {
+            anchor.column = 0;
+            cursor.column = 0;
+        } else {
+            anchor.column = anchor
+                .column
+                .min(lines[anchor.row].chars().count());
+            cursor.column = cursor
+                .column
+                .min(lines[cursor.row].chars().count());
+        }
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.anchor = anchor;
+            selection.cursor = cursor;
+        }
+    }
+
+    fn visual_start_position(&self, pane: PaneFocus, right_content: &str) -> VisualPosition {
+        match pane {
+            PaneFocus::Left => VisualPosition {
+                row: self.left_control_visual_row(),
+                column: 0,
+            },
+            PaneFocus::Right => {
+                let lines = self.visual_lines(PaneFocus::Right, right_content);
+                let last = lines.len().saturating_sub(1);
+                let row = lines
+                    .iter()
+                    .enumerate()
+                    .rev()
+                    .find_map(|(index, line)| {
+                        (line != "chat> " || index == 0).then_some(index)
+                    })
+                    .unwrap_or(last);
+                VisualPosition { row, column: 0 }
+            }
+        }
+    }
+
+    fn left_control_visual_row(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+        let mut row = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            if self.control_selected == visible_position + 1 {
+                return row;
+            }
+            row += 1;
+            let agent = &self.agents[*agent_index];
+            if !agent.modified_files.is_empty() {
+                row += 1;
+            }
+            for linked_agents in [
+                &agent.conflicting_agents,
+                &agent.depends_on,
+                &agent.depended_on_by,
+            ] {
+                if !linked_agents.is_empty() {
+                    row += 1;
+                }
+            }
+        }
+        row.saturating_sub(1)
+    }
+
+    fn visual_cursor_position(&self, right_content: &str) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        let column = selection.cursor.column.min(usize::from(u16::MAX)) as u16;
+        let (row, column) = match selection.pane {
+            PaneFocus::Left => (
+                selection.cursor.row.saturating_add(2),
+                usize::from(column).saturating_add(2),
+            ),
+            PaneFocus::Right => {
+                let layout = self.layout();
+                let lines = self.visual_lines(PaneFocus::Right, right_content);
+                let line_width = lines
+                    .get(selection.cursor.row)
+                    .map(|line| line.chars().count())
+                    .unwrap_or_default();
+                let column = selection.cursor.column.min(line_width);
+                (
+                    selection.cursor.row.saturating_add(2),
+                    usize::from(layout.left_width)
+                        .saturating_add(2)
+                        .saturating_add(column),
+                )
+            }
+        };
+        Some((
+            row.min(usize::from(u16::MAX)) as u16,
+            column.min(usize::from(u16::MAX)) as u16,
+        ))
+    }
+
