use std::error::Error;
use std::fs;
use std::path::Path;
use std::process::Command;
use std::time::Duration;

use work_leaf::{
    CodexBackend, CodexCommandConfig, CommandChat, PromptPolicy, ReadPermission, TerminalApp,
};

const PROMPT: &str = "work-leaf: Review complete. Is this feature done? yes/no";

fn git(root: &Path, args: &[&str]) -> Result<(), Box<dyn Error>> {
    let output = Command::new("git").current_dir(root).args(args).output()?;
    if !output.status.success() {
        return Err(format!(
            "git {:?} failed\nstdout:\n{}\nstderr:\n{}",
            args,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }
    Ok(())
}

fn seed_agent_commit(root: &Path, text: &str, reason: &str) -> Result<(), Box<dyn Error>> {
    fs::write(root.join("README.md"), text)?;
    git(root, &["add", "README.md"])?;
    let body = format!(
        "Agent-ID: user-1\nFeature: real-agent-review-smoke\nReason: {reason}\nContext: README changes for review completion smoke"
    );
    git(
        root,
        &[
            "commit",
            "-m",
            "UPDATE apply real-agent review smoke patch from user-1",
            "-m",
            &body,
        ],
    )?;
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let root = std::env::temp_dir().join(format!(
        "work-leaf-real-review-scenario-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)?;
    git(&root, &["init", "-q"])?;
    git(&root, &["config", "user.email", "test@example.com"])?;
    git(&root, &["config", "user.name", "Test User"])?;
    fs::write(root.join("README.md"), "before\n")?;
    git(&root, &["add", "README.md"])?;
    git(&root, &["commit", "-m", "ADD initial real-agent smoke fixture"])?;

    let policy = PromptPolicy::for_project_with_read_permission(
        &root,
        ReadPermission::DirectFilesystem,
    )?;
    let backend = CodexBackend::new(CodexCommandConfig::new(root.clone()), policy);
    let chat = CommandChat::new(root.clone(), backend).with_max_review_rounds(1);
    let mut app = TerminalApp::new(chat, 100, 24);

    app.handle_bytes(b":new\n");
    if !app.wait_for_idle(Duration::from_secs(120)) {
        return Err("real user-agent launch did not finish within 120s".into());
    }
    println!("real user agent launched");

    seed_agent_commit(&root, "after first review target\n", "first review target")?;
    app.handle_bytes(b"\x1b:review\n");
    if !app.wait_for_idle(Duration::from_secs(180)) {
        return Err("real review did not finish within 180s".into());
    }
    let frame = app.render_frame();
    if !frame.contains(PROMPT) {
        return Err(format!("review completion prompt was not visible\n{frame}").into());
    }
    println!("review completion prompt appeared");

    app.handle_bytes(b"please reply REOPEN_OK and do not modify files\n");
    if !app.wait_for_idle(Duration::from_secs(120)) {
        return Err("real reopen follow-up did not finish within 120s".into());
    }
    let frame = app.render_frame();
    if !frame.contains("work-leaf: feature reopened")
        || !frame.contains("user: please reply REOPEN_OK and do not modify files")
    {
        return Err(format!("non-yes follow-up did not reopen and send to user-1\n{frame}").into());
    }
    println!("non-yes follow-up reopened the patch chat and was sent to user-1");

    seed_agent_commit(&root, "after second review target\n", "second review target")?;
    app.handle_bytes(b"\x1b:review\n");
    if !app.wait_for_idle(Duration::from_secs(180)) {
        return Err("second real review did not finish within 180s".into());
    }
    let frame = app.render_frame();
    if !frame.contains(PROMPT) {
        return Err(format!("second review completion prompt was not visible\n{frame}").into());
    }

    app.handle_bytes(b"yes\n");
    if !app.wait_for_idle(Duration::from_secs(30)) {
        return Err("yes close did not settle within 30s".into());
    }
    if app.ui().selected_agent().is_some() || app.ui().render_left_pane().contains("user-1") {
        return Err(format!(
            "yes did not close/hide the patch chat\nleft pane:\n{}",
            app.ui().render_left_pane()
        )
        .into());
    }
    println!("yes closed and hid the patch chat");
    println!("WORK_LEAF_REAL_REVIEW_COMPLETION_OK");
    Ok(())
}
